#include "material_tears.hpp"
#include <algorithm>
#include <cmath>
#include <functional>
#include <iostream>
#include <limits>
#include <stdexcept>
using namespace web;
using namespace web::physics;
namespace {
void check(bool b,const std::string& s){if(!b)throw std::runtime_error(s);}
bool near(double a,double b,double e=1e-12){return std::abs(a-b)<e;}
bool same(V3 a,V3 b){return a.x==b.x&&a.y==b.y&&a.z==b.z;}
double mass(const Graph&g){double m=0;for(const auto&p:g.particles)if(p.invMass>0)m+=1/p.invMass;return m;}
Graph crossing(bool anchor=false){
 Graph g;g.settings.gravity=0;g.settings.damping=0;g.settings.extremeStrain=100;
 for(V2 uv:std::vector<V2>{{0,.5},{1,.5},{.5,0},{.5,1}}){Particle p;p.id=int(g.particles.size());p.uv=uv;p.rest=p.x={uv.x,uv.y,2};p.invMass=1;g.particles.push_back(p);}
 g.edges={{10,0,1,1,3,1,.01,1e6,0,0,0,.002,true},{20,2,3,2,5,1,.0025,2e6,0,0,0,.006,true}};
 if(anchor){g.anchors={{7,g.particles[0].x}};g.particles[0].anchor=7;g.particles[0].invMass=0;}
 components(g);return g;
}
void noCross(const Graph&g){for(const auto&e:g.edges)if(e.active){auto uv=materialEdgeUV(g,e);for(const auto&r:g.materialTears.cuts)check(!materialCutInterval(r,uv[0],uv[1]),"active segment crosses cut interior");}}
void split_test(){
 auto g=crossing();g.particles[0].v={1,2,3};g.particles[1].v={3,4,5};enableMaterialTears(g,.1);const double m=mass(g);auto result=applyMaterialTear(g,10);
 check(result.regions==1&&result.primaryCuts==1&&result.secondaryCuts==1,"one primary must create one local region and one secondary cut");
 check(g.particles.size()==8&&g.edges.size()==6,"both surviving pieces of each crossing must remain");
 check(g.materialTears.cuts.size()==1,"secondary cut expanded the cut region");
 check(g.events.size()==2&&g.events[0].edge==10&&g.events[1].edge==20&&g.events[1].cause=="secondary-material-tear","deterministic secondary event tag");
 int active=0;double rest=0;for(const auto&e:g.edges)if(e.active){++active;rest+=e.rest;check(near(e.compliance/e.rest,e.kind==1?.01:.0025),"child compliance not proportional");check(e.strength==(e.kind==1?1e6:2e6)&&e.strand==(e.kind==1?3:5),"child material metadata changed");}
 check(active==4&&near(rest,1.6),"surviving rest lengths incorrect");
 check(near(g.particles[4].uv.x,.4)&&near(g.particles[5].uv.x,.6),"new ends do not bound finite hole");
 check(near(g.particles[4].v.x,1.8)&&near(g.particles[5].v.x,2.2),"free ends lost interpolated velocity");
 check(near(mass(g),m)&&g.materialTears.anchorSuppliedMass==0,"free graph mass not conserved");
 noCross(g);validateGraph(g);
}
void anchors_test(){auto g=crossing(true);auto p=g.particles[0];enableMaterialTears(g,.1);const double before=mass(g);applyMaterialTear(g,10);check(same(g.particles[0].x,p.x)&&same(g.particles[0].rest,p.rest)&&same(g.particles[0].v,p.v)&&g.particles[0].invMass==0,"cut moved anchor");check(g.materialTears.anchorSuppliedMass>0&&near(mass(g)-before,g.materialTears.anchorSuppliedMass),"pinned reservoir mass not accounted");for(size_t i=4;i<g.particles.size();++i)check(g.particles[i].anchor==-1&&std::isfinite(g.particles[i].invMass)&&g.particles[i].invMass>0,"new end is pinned or invalid");}
void transactional_test(){auto g=crossing();enableMaterialTears(g,.1,3);auto before=saveState(g);bool rejected=false;try{applyMaterialTear(g,10);}catch(const std::exception&){rejected=true;}check(rejected,"particle reserve overflow did not fail");check(saveState(g)==before&&g.materialTears.cuts.empty(),"failed cut partially mutated graph");}
void cut_mode_test(){auto g=crossing();enableMaterialTears(g,.1);cut(g,10);check(g.materialTears.cuts.size()==1&&g.edges.size()==6,"cut() bypassed local material mode");}
void checkpoint_test(){auto g=crossing();enableMaterialTears(g,.1);applyMaterialTear(g,10);auto saved=saveState(g);check(saved.find("END\nMATERIAL_TEARS 2\n")!=std::string::npos,"tagged checkpoint extension missing");Graph restored;restoreState(restored,saved);check(restored.materialTears.cuts.size()==1&&restored.materialTears.lineage.size()==g.edges.size(),"checkpoint lost material state");check(saveState(restored)==saved,"material checkpoint not byte-exact");for(int i=0;i<20;++i){step(g,{},{{1,{.01,0,0}}});step(restored,{},{{1,{.01,0,0}}});}check(saveState(g)==saveState(restored),"material checkpoint replay differs");auto plain=crossing();check(saveState(plain).find("MATERIAL_TEARS")==std::string::npos,"disabled mode changes legacy checkpoint");auto before=saveState(restored);bool rejected=false;try{restoreState(restored,saved+"garbage");}catch(const std::exception&){rejected=true;}check(rejected&&saveState(restored)==before,"bad material restore not atomic");}
void solver_break_test(){auto g=crossing();g.settings.substeps=4;g.settings.breakDelay=g.settings.dt;g.edges[0].overload=g.settings.dt;g.edges[0].rest=.8;g.edges[0].strength=.01;enableMaterialTears(g,.1);step(g);check(g.materialTears.cuts.size()==1&&g.events.size()==2,"solver did not commit primary and secondary local cuts");check(g.events[0].substep==0,"solver failure not committed at end of first substep");check(g.particles.size()==8,"solver new endpoints missing");noCross(g);validateGraph(g);}
void contact_and_force_test(){auto g=crossing();enableMaterialTears(g,.1);applyMaterialTear(g,10);auto reference=g;Sphere sphere{true,{.5,.5,2},{.5,.5,2},.02};step(g,sphere);step(reference);check(saveState(g)==saveState(reference),"hole retained ghost sphere contact");const auto right=g.particles[1].x;for(int i=0;i<10;++i)step(g,{},{{0,{-10,0,0}}});check(same(g.particles[1].x,right),"force propagated across cut gap");}
void fall_test(){auto g=crossing(true);g.settings.gravity=-9.81;enableMaterialTears(g,.1);applyMaterialTear(g,10);const auto anchor=g.particles[0].x;const double z=g.particles[1].x.z;for(int i=0;i<20;++i)step(g);check(g.particles[1].x.z<z-.05,"disconnected fragment did not fall");check(same(g.particles[0].x,anchor)&&g.particles[0].invMass==0,"anchor changed while fragments fell");}
void deterministic_test(){auto a=crossing(),b=a;std::reverse(b.edges.begin(),b.edges.end());enableMaterialTears(a,.1);enableMaterialTears(b,.1);applyMaterialTearBatch(a,{{20,"manual"},{10,"manual"}});applyMaterialTearBatch(b,{{10,"manual"},{20,"manual"}});std::sort(b.edges.begin(),b.edges.end(),[](auto x,auto y){return x.id<y.id;});check(saveState(a)==saveState(b),"cut result depends on caller or edge storage order");check(a.materialTears.cuts.size()==1,"secondary primary request expanded the cut");for(int i=0;i<20;++i){step(a);step(b);}check(saveState(a)==saveState(b),"post-tear solver order differs");}
void scalar_budget_test(){auto g=crossing();enableMaterialTears(g,.1);g.settings.maxConstraints=5;auto before=saveState(g);bool rejected=false;try{applyMaterialTear(g,10);}catch(const std::exception&){rejected=true;}check(rejected&&saveState(g)==before,"scalar overflow partially committed topology");g.settings.maxConstraints=6;before=saveState(g);rejected=false;try{applyMaterialTearBatch(g,{{10,"manual"}},0,1);}catch(const std::exception&){rejected=true;}check(rejected&&saveState(g)==before,"contact scalar budget omitted from preflight");}
void repeat_child_test(){auto g=crossing();enableMaterialTears(g,.05);applyMaterialTear(g,10);const int child=g.edges[2].id;const double oldRest=g.edges[2].rest;applyMaterialTear(g,child);check(g.materialTears.cuts.size()==2,"child failure did not create next bounded region");noCross(g);check(g.materialTears.lineage.back().parentEdge==child,"child lineage lost parent");check(g.materialTears.lineage.back().rootEdge==10,"child lineage lost root");double rest=0;for(const auto&e:g.edges)if(e.active&&e.strand==3)rest+=e.rest;check(near(rest,.8)&&oldRest>.1,"second cut destroyed surviving material");}

void convex_interval_test(){MaterialCutRegion r;r.polygon={{.4,.4},{.6,.4},{.6,.6},{.4,.6}};auto interval=materialCutInterval(r,{0,.5},{1,.5});check(interval&&near((*interval)[0],.4)&&near((*interval)[1],.6),"convex interior interval incorrect");check(!materialCutInterval(r,{0,.4},{1,.4}),"boundary tangent incorrectly removed");check(!materialCutInterval(r,{0,.2},{.4,.6}),"vertex tangent incorrectly removed");interval=materialCutInterval(r,{.5,.5},{.5,.5});check(interval&&(*interval)[0]==0&&(*interval)[1]==1,"interior degenerate UV edge not fully removed");check(pointInMaterialCut(r,{.4,.5})&&pointInMaterialCut(r,{.5,.5})&&!pointInMaterialCut(r,{.7,.5}),"polygon coverage mismatch");}
void exact_material_chart_test(){auto g=crossing();g.cohesive.enabled=true;for(const auto&p:g.particles)g.cohesive.vertices.push_back({p.uv,p.rest,p.id});g.cohesive.segments={{0,1,10,10},{2,3,20,20}};g.particles[0].uv={.1,.5};enableMaterialTears(g,.1);applyMaterialTear(g,10);check(near(g.particles[4].uv.x,.4)&&near(g.particles[5].uv.x,.6),"cut center used contracted physical chart");check(near(g.materialTears.cuts[0].polygon[0].x,.6),"cut polygon midpoint lost exact material UV");}
void whole_edge_test(){auto g=crossing();g.particles[2].uv={.49,.49};g.particles[3].uv={.51,.51};enableMaterialTears(g,.1);applyMaterialTear(g,10);check(g.edges.size()==4&&g.particles.size()==6&&!g.edges[1].active,"fully interior strand retained constraint");noCross(g);}
void one_sided_test(){auto g=crossing();g.particles[2].uv={.5,.5};g.particles[3].uv={.5,1};enableMaterialTears(g,.1);applyMaterialTear(g,10);check(g.edges.size()==5&&g.particles.size()==7,"one-sided secondary clipping lost surviving piece");check(g.edges.back().a>=4&&g.edges.back().b==3&&near(g.edges.back().rest,.8),"one-sided child endpoints or rest incorrect");check(pointInMaterialCut(g,g.events.back().uv),"secondary event position lies outside its actual cut region");noCross(g);}
void batch_atomic_test(){auto g=crossing();g.particles[2].uv={0,.8};g.particles[3].uv={1,.8};enableMaterialTears(g,.1,3);auto before=saveState(g);bool rejected=false;try{applyMaterialTearBatch(g,{{10,"manual"},{20,"manual"}});}catch(const std::exception&){rejected=true;}check(rejected&&saveState(g)==before,"later primary budget failure partially committed earlier cut");}
void invalid_material_state_test(){auto g=crossing();enableMaterialTears(g,.1);applyMaterialTear(g,10);auto rejects=[](Graph bad){bool rejected=false;try{validateGraph(bad);}catch(const std::exception&){rejected=true;}check(rejected,"invalid material state accepted");};auto bad=g;bad.materialTears.lineage.back().parentT0=.8;bad.materialTears.lineage.back().parentT1=.7;rejects(bad);bad=g;bad.materialTears.cuts[0].polygon[1]=bad.materialTears.cuts[0].polygon[0];rejects(bad);bad=g;bad.materialTears.primaryCuts=2;rejects(bad);bad=g;bad.materialTears.lineage.back().uvA={.5,.5};rejects(bad);}

void invalid_contact_budget_test(){auto g=crossing();enableMaterialTears(g,.1);auto before=saveState(g);bool rejected=false;try{applyMaterialTearBatch(g,{{10,"manual"}},0,std::numeric_limits<std::size_t>::max());}catch(const std::exception&){rejected=true;}check(rejected&&saveState(g)==before,"contact count overflow bypassed material scalar budget");}

void shared_junction_order_test(){auto a=crossing();a.edges[0].rest=1e8;for(V2 uv:std::vector<V2>{{-1,.5},{0,1}}){Particle p;p.id=int(a.particles.size());p.uv=uv;p.rest=p.x={uv.x,uv.y,2};a.particles.push_back(p);}a.edges.push_back({30,0,4,1,6,1e-8,.01,1e6,0,0,0,.002,true});a.edges.push_back({40,0,5,1,7,1e-8,.01,1e6,0,0,0,.002,true});auto b=a;std::reverse(b.edges.begin(),b.edges.end());enableMaterialTears(a,.1);enableMaterialTears(b,.1);applyMaterialTear(a,10);applyMaterialTear(b,10);std::sort(b.edges.begin(),b.edges.end(),[](auto x,auto y){return x.id<y.id;});check(saveState(a)==saveState(b),"shared-junction mass reduction depends on edge storage order");}

void particle_chart_test(){auto g=crossing();g.cohesive.enabled=true;for(const auto&p:g.particles)g.cohesive.vertices.push_back({p.uv,p.rest,p.id});g.cohesive.segments={{0,1,10,10},{2,3,20,20}};const auto authored=g.cohesive.vertices;g.particles[0].uv={.1,.6};const V2 a=g.particles[0].uv,b=g.particles[1].uv;enableMaterialTears(g,.1,128,MaterialChartSource::ParticleUV);applyMaterialTear(g,10);for(const auto&line:g.materialTears.lineage)if(line.parentEdge==10)for(V2 uv:{line.uvA,line.uvB}){const V2 u=b-a,v=uv-a;check(std::abs(u.x*v.y-u.y*v.x)<1e-12,"ParticleUV child left parent particle-UV line");}for(size_t i=0;i<authored.size();++i)check(g.cohesive.vertices[i].uv.x==authored[i].uv.x&&g.cohesive.vertices[i].uv.y==authored[i].uv.y,"chart selection mutated authored UV metadata");Graph restored;restoreState(restored,saveState(g));check(restored.materialTears.chartSource==MaterialChartSource::ParticleUV,"checkpoint lost ParticleUV chart mode");check(saveState(restored)==saveState(g),"ParticleUV checkpoint not exact");auto bad=g;bad.materialTears.chartSource=static_cast<MaterialChartSource>(99);bool rejected=false;try{validateGraph(bad);}catch(const std::exception&){rejected=true;}check(rejected,"invalid material chart enum accepted");}

}
int main(){int failed=0;const std::pair<const char*,void(*)()> cases[]={{"local_split",split_test},{"exact_anchors",anchors_test},{"transactional_budget",transactional_test},{"cut_mode",cut_mode_test},{"checkpoint_replay",checkpoint_test},{"solver_substep_commit",solver_break_test},{"no_gap_force_or_contact",contact_and_force_test},{"disconnected_fall",fall_test},{"deterministic_event_order",deterministic_test},{"scalar_budget",scalar_budget_test},{"repeat_child_cut",repeat_child_test},{"convex_interval",convex_interval_test},{"exact_material_chart",exact_material_chart_test},{"whole_interior_edge",whole_edge_test},{"one_sided_fragment",one_sided_test},{"whole_batch_atomic",batch_atomic_test},{"invalid_material_state",invalid_material_state_test},{"contact_count_overflow",invalid_contact_budget_test},{"shared_junction_order",shared_junction_order_test},{"particle_uv_chart",particle_chart_test}};for(auto c:cases)try{c.second();std::cout<<"PASS "<<c.first<<'\n';}catch(const std::exception&e){++failed;std::cerr<<"FAIL "<<c.first<<": "<<e.what()<<'\n';}return failed?1:0;}
